    private static array $lock_depth=[];

    private static function with_lock(string $name,callable $callback){$depth=(int)(self::$lock_depth[$name]??0);if($depth>0){self::$lock_depth[$name]=$depth+1;try{return $callback();}finally{self::$lock_depth[$name]--;}}global $wpdb;$advisory='xwmcp_'.substr(hash_hmac('sha256',$name,wp_salt('auth')),0,32);$handle='';if(is_object($wpdb)&&method_exists($wpdb,'prepare')&&method_exists($wpdb,'get_var')){if((int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, 5)',$advisory))!==1)throw new RuntimeException('Another protected operation is in progress.');$handle='mysql:'.$advisory;}else{$owner=bin2hex(random_bytes(12));$value=['owner'=>$owner,'expires'=>time()+2*HOUR_IN_SECONDS];if(!add_option($name,$value,'','no')){$held=get_option($name);if(is_array($held)&&(int)($held['expires']??0)<time()){delete_option($name);if(!add_option($name,$value,'','no'))throw new RuntimeException('Another protected operation is in progress.');}else throw new RuntimeException('Another protected operation is in progress.');}$handle='option:'.$owner;}self::$lock_depth[$name]=1;try{return $callback();}finally{self::$lock_depth[$name]=0;if(str_starts_with($handle,'mysql:')){$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',substr($handle,6)));}else{$held=get_option($name);$owner=substr($handle,7);if(is_array($held)&&hash_equals($owner,(string)($held['owner']??'')))delete_option($name);}}}

    public static function validate_plugin_basename(string $plugin):string {
        $plugin=wp_normalize_path(trim($plugin));
        if($plugin===''||str_starts_with($plugin,'/')||str_contains($plugin,'..')||!preg_match('#^[A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+)*\.php$#',$plugin))throw new InvalidArgumentException('Invalid plugin basename.');
        if($plugin==='xsofty-wordpress-mcp/xsofty-wordpress-mcp.php')throw new InvalidArgumentException('The MCP bridge cannot update or restore itself.');
        return $plugin;
    }

    public static function cron_event_id(int $timestamp,string $hook,string $schedule,array $args):string {return substr(hash_hmac('sha256',$timestamp.'|'.$hook.'|'.$schedule.'|'.serialize($args),wp_salt('auth')),0,24);}

    private static function checkpoint_directory():string {$dir=Xsofty_MCP_Backups::snapshots_directory().'/plugins';if(is_link($dir)||(!is_dir($dir)&&!wp_mkdir_p($dir)))throw new RuntimeException('Unable to create private plugin checkpoint storage.');$real=realpath($dir);if($real===false||wp_normalize_path($real)!==wp_normalize_path($dir)||!chmod($dir,0700)||(fileperms($dir)&0777)!==0700||!is_writable($dir))throw new RuntimeException('Plugin checkpoint storage is not securely writable.');return $real;}

    private static function plugin_inventory():array {if(!function_exists('get_plugins'))require_once ABSPATH.'wp-admin/includes/plugin.php';return get_plugins();}

    private static function source_for(string $plugin):array {
