    }

    private static function add_source(ZipArchive $zip,string $root,string $prefix,string $stage):array {$files=0;$bytes=0;if(is_file($root)){if(is_link($root))throw new RuntimeException('Unable to checkpoint plugin file.');$snapshot=$stage.'/'.$prefix;Xsofty_MCP_Backups::snapshot_file($root,$snapshot);if(!$zip->addFile($snapshot,$prefix))throw new RuntimeException('Unable to checkpoint plugin file.');return ['files'=>1,'bytes'=>(int)filesize($snapshot)];}$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($iterator as $item){if($item->isLink())throw new RuntimeException('Plugin checkpoints reject symlinks.');$relative=ltrim(substr(wp_normalize_path($item->getPathname()),strlen(trailingslashit(wp_normalize_path($root)))),'/');$archive=trim($prefix.'/'.$relative,'/');if($item->isDir()){if(!$zip->addEmptyDir($archive))throw new RuntimeException('Unable to checkpoint plugin directory.');continue;}$size=(int)$item->getSize();if($size>100*MB_IN_BYTES||$bytes+$size>500*MB_IN_BYTES)throw new RuntimeException('Plugin checkpoint exceeds the size limit.');$snapshot=$stage.'/'.$archive;Xsofty_MCP_Backups::snapshot_file($item->getPathname(),$snapshot);if(!$zip->addFile($snapshot,$archive))throw new RuntimeException('Unable to checkpoint plugin file.');$files++;$bytes+=$size;}return ['files'=>$files,'bytes'=>$bytes];}

    public static function create_checkpoint(string $plugin):array {return self::with_lock(self::OPERATION_LOCK,function()use($plugin):array {if(is_multisite())throw new RuntimeException('Plugin checkpoint operations are disabled on multisite until a network policy is configured.');$source=self::source_for($plugin);$dir=self::checkpoint_directory();$id=bin2hex(random_bytes(8));$filename='plugin-'.sanitize_title(str_replace('/','-',$source['plugin'])).'-'.gmdate('Ymd-His').'-'.$id.'.zip';$part=$dir.'/'.$filename.'.part';$final=$dir.'/'.$filename;$source_stage=$dir.'/.source-'.$id;if(!mkdir($source_stage,0700)||is_link($source_stage)||(fileperms($source_stage)&0777)!==0700)throw new RuntimeException('Unable to create secure checkpoint staging.');$zip=new ZipArchive();if($zip->open($part,ZipArchive::CREATE|ZipArchive::EXCL)!==true){self::remove_tree($source_stage);throw new RuntimeException('Unable to create plugin checkpoint.');}try{$stats=self::add_source($zip,$source['root'],$source['prefix'],$source_stage);$manifest=['format'=>1,'id'=>$id,'plugin'=>$source['plugin'],'version'=>$source['version'],'prefix'=>$source['prefix'],'created_at'=>gmdate('c'),'files'=>$stats['files'],'bytes'=>$stats['bytes']];if(!$zip->addFromString('.xsofty-plugin-checkpoint.json',wp_json_encode($manifest,JSON_UNESCAPED_SLASHES)))throw new RuntimeException('Unable to add checkpoint manifest.');if(!$zip->close())throw new RuntimeException('Unable to finalize checkpoint.');}catch(Throwable $e){$zip->close();@unlink($part);self::remove_tree($source_stage);throw $e;}self::remove_tree($source_stage);if(file_exists($source_stage)||is_link($source_stage)){@unlink($part);throw new RuntimeException('Unable to clean plugin checkpoint staging; the checkpoint was not published.');}$check=new ZipArchive();if($check->open($part,ZipArchive::CHECKCONS)!==true||$check->locateName('.xsofty-plugin-checkpoint.json')===false){if($check->status===ZipArchive::ER_OK)$check->close();@unlink($part);throw new RuntimeE