    public static function list_checkpoints():array {if(is_multisite())throw new RuntimeException('Plugin checkpoint operations are disabled on multisite until a network policy is configured.');$items=[];$dir=self::checkpoint_directory();foreach((array)get_option(self::CHECKPOINT_OPTION,[]) as $id=>$record){$file=$dir.'/'.basename((string)($record['filename']??''));if(is_file($file))$items[]=array_diff_key($record,['filename'=>true]);}return ['items'=>array_values($items),'count'=>count($items)];}

    private static function remove_tree(string $path):void {for($attempt=0;$attempt<10;$attempt++){if(is_link($path)||is_file($path)){@unlink($path);if(!file_exists($path)&&!is_link($path))return;}elseif(!is_dir($path))return;else{foreach(new FilesystemIterator($path,FilesystemIterator::SKIP_DOTS) as $item)self::remove_tree($item->getPathname());if(@rmdir($path))return;}clearstatcache(true,$path);usleep(50000);}}

    private static function extract_checkpoint(array $record):array {$dir=self::checkpoint_directory();$file=$dir.'/'.basename((string)$record['filename']);if(!is_file($file))throw new RuntimeException('Plugin checkpoint archive is missing.');$actual=hash_file('sha256',$file);if(!is_string($actual)||!hash_equals((string)($record['sha256']??''),$actual))throw new RuntimeException('Plugin checkpoint hash verification failed.');$zip=new ZipArchive();if($zip->open($file,ZipArchive::CHECKCONS)!==true)throw new RuntimeException('Plugin checkpoint archive is invalid.');$raw=$zip->getFromName('.xsofty-plugin-checkpoint.json');$manifest=json_decode((string)$raw,true);$expected_prefix=str_contains((string)$record['plugin'],'/')?dirname((string)$record['plugin']):basename((string)$record['plugin']);if(!is_array($manifest)||($manifest['id']??'')!==$record['id']||($manifest['plugin']??'')!==$record['plugin']||($manifest['prefix']??'')!==$expected_prefix){$zip->close();throw new RuntimeException('Plugin checkpoint manifest mismatch.');}$stage=WP_PLUGIN_DIR.'/.xwmcp-stage-'.bin2hex(random_bytes(6));if(!mkdir($stage,0700)){$zip->close();throw new RuntimeException('Unable to stage plugin restore.');}try{$declared_files=(int)($manifest['files']??-1);$declared_bytes=(int)($manifest['bytes']??-1);if(($manifest['format']??0)!==1||$declared_files<1||$declared_files>50000||$declared_bytes<0||$declared_bytes>500*MB_IN_BYTES||$zip->numFiles>50001)throw new RuntimeException('Plugin checkpoint manifest limits are invalid.');$extracted_files=0;$extracted_bytes=0;for($i=0;$i<$zip->numFiles;$i++){$name=$zip->getNameIndex($i);if($name==='.xsofty-plugin-checkpoint.json')continue;$name=wp_normalize_path($name);if($name===''||str_starts_with($name,'/')||str_contains($name,'../')||str_contains($name,'\\')||str_contains($name,':')||str_contains($name,"\0"))throw new RuntimeException('Unsafe checkpoint entry.');if(!str_starts_with($name,$manifest['prefix'].'/')&&$name!==$manifest['prefix'])throw new Ru