    public static function restore_checkpoint(string $id):array {return self::with_lock(self::OPERATION_LOCK,function()use($id):array {if(is_multisite())throw new RuntimeException('Plugin checkpoint operations are disabled on multisite until a network policy is configured.');$id=sanitize_key($id);$records=(array)get_option(self::CHECKPOINT_OPTION,[]);$record=$records[$id]??null;if(!$record)throw new RuntimeException('Plugin checkpoint not found.');$plugin=self::validate_plugin_basename((string)$record['plugin']);$extracted=self::extract_checkpoint($record);$stage=$extracted['stage'];$prefix=$extracted['manifest']['prefix'];$target=WP_PLUGIN_DIR.'/'.$prefix;$staged=$stage.'/'.$prefix;$old=WP_PLUGIN_DIR.'/.xwmcp-old-'.bin2hex(random_bytes(6));if(!file_exists($staged)){self::remove_tree($stage);throw new RuntimeException('Checkpoint plugin root is missing.');}$quarantined=false;$published=false;$validated=false;try{if(file_exists($target)){if(!rename($target,$old))throw new RuntimeException('Unable to quarantine current plugin version.');$quarantined=true;}if(!rename($staged,$target))throw new RuntimeException('Unable to publish restored plugin version.');$published=true;if(!is_file(WP_PLUGIN_DIR.'/'.$plugin)||is_link(WP_PLUGIN_DIR.'/'.$plugin))throw new RuntimeException('Restored plugin entry file is missing or unsafe.');if(function_exists('wp_clean_plugins_cache'))wp_clean_plugins_cache(false);$plugins=self::plugin_inventory();if(!isset($plugins[$plugin])||!hash_equals((string)$record['version'],(string)($plugins[$plugin]['Version']??'')))throw new RuntimeException('Restored plugin failed identity or version validation.');$validated=true;self::remove_tree($stage);if(file_exists($stage)||is_link($stage))throw new RuntimeException('Unable to clean plugin restore staging.');self::remove_tree($old);if(file_exists($old)||is_link($old))throw new RuntimeException('Unable to clean the quarantined plugin after restore.');}catch(Throwable $e){if($validated){self::remove_tree($