    public static function plugin_updates():array {if(is_multisite())throw new RuntimeException('Plugin updates are disabled on multisite until a network policy is configured.');$updates=get_site_transient('update_plugins');$plugins=self::plugin_inventory();$items=[];foreach((array)($updates->response??[]) as $plugin=>$update){if($plugin==='xsofty-wordpress-mcp/xsofty-wordpress-mcp.php')continue;$items[]=['plugin'=>$plugin,'name'=>(string)($plugins[$plugin]['Name']??$plugin),'current_version'=>(string)($plugins[$plugin]['Version']??''),'new_version'=>(string)($update->new_version??''),'package_available'=>!empty($update->package)];}return ['items'=>$items,'count'=>count($items)];}

    public static function update_plugin(string $plugin,string $expected_current_version,string $expected_new_version):array {return self::with_lock(self::OPERATION_LOCK,function()use($plugin,$expected_current_version,$expected_new_version):array {if(is_multisite())throw new RuntimeException('Plugin updates are disabled on multisite until a network policy is configured.');$plugin=self::validate_plugin_basename($plugin);if(!current_user_can('update_plugins'))throw new RuntimeException('The MCP service user cannot update plugins.');$source=self::source_for($plugin);if($expected_current_version===''||!hash_equals($source['version'],$expected_current_version))throw new RuntimeException('Installed plugin version changed; refresh the update plan.');$updates=get_site_transient('update_plugins');$update=$updates->response[$plugin]??null;$advertised=(string)($update->new_version??'');if(!$update||empty($update->package)||$expected_new_version===''||!hash_equals($advertised,$expected_new_version))throw new RuntimeException('Advertised plugin update changed; refresh the update plan.');$checkpoint=self::create_checkpoint($plugin);require_once ABSPATH.'wp-admin/includes/class-wp-upgrader.php';$skin=new Automatic_Upgrader_Skin();$upgrader=new Plugin_Upgrader($skin);$result=$upgrader->upgrade($plugin,['clear_update_cache'=>true]);if(is_wp_error($result)||$result===false){try{self::restore_checkpoint($checkpoint['id']);}catch(Throwable $rollback){throw new RuntimeException('Plugin update failed and automatic rollback also failed. Manual recovery is required.');}throw new RuntimeException('Plugin update failed; the previous checkpoint was restored.');}if(function_exists('wp_clean_plugins_cache'))wp_clean_plugins_cache(false);$plugins=self::plugin_inventory();if(!isset($plugins[$plugin])||!hash_equals($expected_new_version,(string)($plugins[$plugin]['Version']??''))){self::restore_checkpoint($checkpoint['id']);throw new RuntimeException('Updated plugin failed target-version validatio