    public static function cron_events(int $limit=100):array {$events=[];$limit=max(1,min(200,$limit));foreach((array)_get_cron_array() as $timestamp=>$hooks)foreach((array)$hooks as $hook=>$instances)foreach((array)$instances as $instance){$args=(array)($instance['args']??[]);$events[]=['event_id'=>self::cron_event_id((int)$timestamp,(string)$hook,(string)($instance['schedule']??''),$args),'hook'=>(string)$hook,'next_run_gmt'=>gmdate('c',(int)$timestamp),'overdue'=>(int)$timestamp<time()-300,'schedule'=>(string)($instance['schedule']??''),'interval'=>(int)($instance['interval']??0),'args_count'=>count($args),'args_sha256'=>hash('sha256',serialize($args)),'timestamp'=>(int)$timestamp,'_args'=>$args];}usort($events,static fn($a,$b)=>$a['timestamp']<=>$b['timestamp']);$public=[];foreach(array_slice($events,0,$limit) as $event){unset($event['timestamp'],$event['_args']);$public[]=$event;}return ['items'=>$public,'count'=>count($public)];}

    public static function run_cron(string $event_id):array {return self::with_lock(self::CRON_LOCK,function()use($event_id):array {$settings=Xsofty_MCP_Auth::settings();if(empty($settings['allow_cron_run']))throw new RuntimeException('Manual cron execution is disabled in MCP settings.');if(!current_user_can('manage_options'))throw new RuntimeException('The MCP service user cannot run cron events.');foreach((array)_get_cron_array() as $timestamp=>$hooks)foreach((array)$hooks as $hook=>$instances)foreach((array)$instances as $instance){$args=(array)($instance['args']??[]);$id=self::cron_event_id((int)$timestamp,(string)$hook,(string)($instance['schedule']??''),$args);if(hash_equals($id,$event_id)){do_action_ref_array($hook,$args);return ['event_id'=>$id,'hook'=>$hook,'ran'=>true,'scheduled_timestamp'=>(int)$timestamp];}}throw new RuntimeException('Scheduled cron event not found.');});}

    public static function health():array {$cron=self::cron_events(200);$overdue=count(array_filter($cron['items'],static fn($event)=>!empty($event['overdue'])));$updates=is_multisite()?null:self::plugin_updates();return ['wordpress'=>get_bloginfo('version'),'php'=>PHP_VERSION,'environment'=>wp_get_environment_type(),'https'=>is_ssl(),'multisite'=>is_multisite(),'debug'=>(bool)(defined('WP_DEBUG')&&WP_DEBUG),'memory_limit'=>ini_get('memory_limit'),'disk_free_bytes'=>($free=@disk_free_space(ABSPATH))===false?null:(int)$free,'cron_events'=>$cron['count'],'overdue_cron_events'=>$overdue,'plugin_updates'=>$updates===null?null:$updates['count'],'plugin_update_inspection'=>$updates===null?'disabled_on_multisite':'available','object_cache'=>(bool)wp_using_ext_object_cache(),'rest_url'=>rest_url()];}
